def cmp_semver(a, b):
    def parse_semver(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version = version.split('+')[0]

        # Split into core and pre-release
        if '-' in version:
            core, pre = version.split('-', 1)
        else:
            core, pre = version, None

        # Parse major.minor.patch
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if pre is not None:
            pre_ids = []
            for ident in pre.split('.'):
                if ident.isdigit():
                    pre_ids.append(int(ident))
                else:
                    pre_ids.append(ident)
        else:
            pre_ids = None

        return (major, minor, patch, pre_ids)

    def compare_pre(pre_a, pre_b):
        # If both have no pre-release, they are equal
        if pre_a is None and pre_b is None:
            return 0
        # If a has pre-release and b doesn't, a is less (pre-release sorts before release)
        if pre_a is not None and pre_b is None:
            return -1
        # If a doesn't have pre-release and b does, a is greater
        if pre_a is None and pre_b is not None:
            return 1

        # Both have pre-release identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                # pre_a is shorter, so pre_a < pre_b
                return -1
            if i >= len(pre_b):
                # pre_b is shorter, so pre_a > pre_b
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # If both are numeric, compare numerically
            if isinstance(id_a, int) and isinstance(id_b, int):
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
            # If both are strings, compare lexically
            elif isinstance(id_a, str) and isinstance(id_b, str):
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
            # Numeric identifiers always have lower precedence than alphanumeric
            elif isinstance(id_a, int) and isinstance(id_b, str):
                return -1
            elif isinstance(id_a, str) and isinstance(id_b, int):
                return 1

        return 0

    def compare_versions(a, b):
        major_a, minor_a, patch_a, pre_a = a
        major_b, minor_b, patch_b, pre_b = b

        if major_a != major_b:
            return -1 if major_a < major_b else 1
        if minor_a != minor_b:
            return -1 if minor_a < minor_b else 1
        if patch_a != patch_b:
            return -1 if patch_a < patch_b else 1

        return compare_pre(pre_a, pre_b)

    parsed_a = parse_semver(a)
    parsed_b = parse_semver(b)

    return compare_versions(parsed_a, parsed_b)
