def parse_range(header, size):
    if not header or not header.startswith("bytes="):
        return None

    range_spec = header[6:]

    if not range_spec:
        return None

    ranges = []
    parts = range_spec.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            return None

        if "-" not in part:
            return None

        left, right = part.split("-", 1)
        left = left.strip()
        right = right.strip()

        if not left and not right:
            return None

        if left and not right:
            # Range like "500-"
            try:
                start = int(left)
            except ValueError:
                return None
            if start < 0:
                return None
            if start >= size:
                continue
            end = size - 1
            ranges.append((start, end))
        elif not left and right:
            # Suffix range like "-500"
            try:
                suffix_len = int(right)
            except ValueError:
                return None
            if suffix_len <= 0:
                return None
            if suffix_len >= size:
                ranges.append((0, size - 1))
            else:
                start = size - suffix_len
                end = size - 1
                ranges.append((start, end))
        else:
            # Range like "0-499"
            try:
                start = int(left)
                end = int(right)
            except ValueError:
                return None
            if start < 0 or end < 0:
                return None
            if start > end:
                return None
            if start >= size:
                continue
            if end >= size:
                end = size - 1
            ranges.append((start, end))

    if not ranges:
        return None

    return ranges
