class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = {}  # freq -> OrderedDict of keys
        self.min_freq = 0

    def _update(self, key):
        freq = self.key_to_freq[key]
        self.freq_to_keys[freq].pop(key)
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        self.key_to_freq[key] = freq + 1
        if freq + 1 not in self.freq_to_keys:
            self.freq_to_keys[freq + 1] = {}
        self.freq_to_keys[freq + 1][key] = None  # Using dict as ordered set (Python 3.7+ preserves insertion order)

    def get(self, key: int) -> int:
        if self.capacity == 0 or key not in self.key_to_val:
            return -1
        self._update(key)
        return self.key_to_val[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update(key)
            return
        if len(self.key_to_val) == self.capacity:
            # Evict least frequently used, then least recently used
            evict_key, _ = next(iter(self.freq_to_keys[self.min_freq].items()))
            del self.freq_to_keys[self.min_freq][evict_key]
            if not self.freq_to_keys[self.min_freq]:
                del self.freq_to_keys[self.min_freq]
            del self.key_to_val[evict_key]
            del self.key_to_freq[evict_key]
        self.key_to_val[key] = value
        self.key_to_freq[key] = 1
        if 1 not in self.freq_to_keys:
            self.freq_to_keys[1] = {}
        self.freq_to_keys[1][key] = None
        self.min_freq = 1
