def next_fire(expr, after):
    """
    Returns the next datetime strictly after `after` at which the given 5-field cron expression fires.
    The cron expression has the format: minute hour day-of-month month day-of-week
    Each field supports: *, a number, a-b, */s, a-b/s, and comma-separated lists of those.
    Day-of-week is 0-6 with 0 = Sunday.
    Raises ValueError on a malformed expression.
    """
