    # Parse each field into a set of valid values
    minutes = parse_field(minute_str, 0, 59)
    hours = parse_field(hour_str, 0, 23)
    days_of_month = parse_field(dom_str, 1, 31)
    months = parse_field(month_str, 1, 12)
    days_of_week = parse_field(dow_str, 0, 6)

    # Determine if day-of-month and day-of-week are restricted
    dom_restricted = dom_str != '*'
    dow_restricted = dow_str != '*'

    # Start searching from the next second after `after`
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(seconds=1)

    # We need to find the next valid datetime
    # To avoid infinite loops, set a reasonable upper bound (e.g., 2 years ahead)
    max_date = after + datetime.timedelta(days=730)

    while current <= max_date:
