        elif dom_restricted:
            if current.day in days_of_month:
                return current
        elif dow_restricted:
            if current.weekday_to_cron() in days_of_week:
                return current

        # Move to the next day
        current += datetime.timedelta(days=1)

        # If we've gone too far, break
        if current.year > year + 2:
            break

