    """Move to the next valid hour."""
    hour = current.hour
    for _ in range(24):
        hour += 1
        if hour > 23:
            hour = 0
            # Move to the next day
            current = current.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            return current
        if hour in hours:
            return current.replace(hour=hour, minute=0)
    raise ValueError("No valid hour found")

