def evaluate(expr):
    """
    Evaluate an arithmetic expression string and return a number.
    Supports integers, decimals, +, -, *, /, %, **, parentheses, unary minus and plus.
    Precedence (loosest to tightest): + -, * / %, **, unary.
    ** is right-associative and binds tighter than unary minus on its left.
    / is true division.
    Raises ValueError on malformed expression.
    Does not use eval or exec.
    """
    import re

    # Tokenizer
    # Tokens: NUMBER, PLUS, MINUS, STAR, SLASH, PERCENT, DOUBLESTAR, LPAREN, RPAREN
    token_spec = [
        ('NUMBER', r'-?\d+\.?\d*'),  # This will match negative numbers, but we handle unary separately
        ('PLUS', r'\+'),
        ('MINUS', r'-'),
        ('STAR', r'\*'),
        ('SLASH', r'/'),
        ('PERCENT', r'%'),
        ('DOUBLESTAR', r'\*\*'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('SKIP', r'[ \t]+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_spec)

    def tokenize(expression):
        tokens = []
        for mo in re.finditer(tok_regex, expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ValueError(f"Unexpected character: {value}")
            elif kind == 'NUMBER':
                # Check if this number was actually a unary minus followed by a number
                # We'll handle unary in the parser, so let's split if it starts with -
                if value.startswith('-'):
                    # This is a unary minus followed by a number
                    tokens.append(('MINUS', '-'))
                    num_str = value[1:]
                    if num_str:
                        tokens.append(('NUMBER', num_str))
                    else:
                        raise ValueError("Invalid number")
                else:
                    tokens.append(('NUMBER', value))
            elif kind == 'PLUS':
                tokens.append(('PLUS', '+'))
            elif kind == 'MINUS':
                tokens.append(('MINUS', '-'))
            elif kind == 'STAR':
                # Check if next char is * for **
                # Actually, the regex should handle ** first if ordered correctly
                # Let's ensure DOUBLESTAR is checked before STAR
                tokens.append(('STAR', '*'))
            elif kind == 'SLASH':
