        tok = peek()
        if tok and tok[0] in ('PLUS', 'MINUS'):
            op = consume()
            operand = parse_unary()
            if op[0] == 'PLUS':
                return +operand
            else:
                return -operand
        else:
            return parse_factor()

    def parse_factor():
        tok = peek()
        if not tok:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUMBER':
            consume()
            return float(tok[1])
        elif tok[0] == 'LPAREN':
            consume()
            result = parse_expr()
            if not peek() or peek()[0] != 'RPAREN':
                raise ValueError("Missing closing parenthesis")
            consume()
            return result
        else:
            raise ValueError(f"Unexpected token: {tok}")

