    for i in range(k):
        add_to_heaps(a[i])
    rebalance()

    result = [get_median()]

    # Slide the window
    for i in range(k, n):
        # Remove a[i-k]
        old_val = a[i - k]
        # Determine which heap the old value is in
        if -old_val <= -left_heap[0]:
            left_to_remove[-old_val] = left_to_remove.get(-old_val, 0) + 1
        else:
            right_to_remove[old_val] = right_to_remove.get(old_val, 0) + 1

