class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.num_components = n
        self.snapshot_counter = 0

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.num_components -= 1
        self.history.append((root_b, root_a))
        return True

    def snapshot(self):
        token = self.snapshot_counter
        self.snapshot_counter += 1
        return token

    def rollback(self, token):
        while self.history and self.history[-1][1] != token:
            child, parent = self.history.pop()
            self.parent[child] = child
            self.size[parent] -= self.size[child]
            self.num_components += 1
        if self.history and self.history[-1][1] == token:
            self.history.pop()

    def components(self):
        return self.num_components
