    def _copy(o):
        if o is None or isinstance(o, (bool, int, float, str)):
            return o
        if id(o) in memo:
            return memo[id(o)]
        if isinstance(o, dict):
            memo[id(o)] = {}
            result = memo[id(o)]
            for k, v in o.items():
                result[_copy(k)] = _copy(v)
