            result = memo[id(o)]
            for item in o:
                result.append(_copy(item))
            return result
        if isinstance(o, set):
            memo[id(o)] = set()
            result = memo[id(o)]
            for item in o:
                result.add(_copy(item))
            return result
        if isinstance(o, tuple):
            memo[id(o)] = []
            result = tuple(_copy(item) for item in o)
            memo[id(o)] = result
            return result
