def to_base(n, alphabet):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not alphabet or len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must be a non-empty string with distinct characters")

    if n == 0:
        return alphabet[0]

    sign = ''
    if n < 0:
        sign = '-'
        n = -n

    base = len(alphabet)
    digits = []
    while n > 0:
        n, rem = divmod(n, base)
        digits.append(alphabet[rem])

    return sign + ''.join(reversed(digits))


def from_base(s, alphabet):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if not alphabet or len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must be a non-empty string with distinct characters")

    if not s:
        raise ValueError("empty string")

    # Check for negative sign
    sign = 1
    start = 0
    if s[0] == '-':
        sign = -1
        start = 1
        if len(s) == 1:
            raise ValueError("invalid string: '-' alone")

    # Validate all characters are in alphabet
    for ch in s[start:]:
        if ch not in alphabet:
            raise ValueError(f"character '{ch}' not in alphabet")

    base = len(alphabet)
    value = 0
    for ch in s[start:]:
        value = value * base + alphabet.index(ch)

    return sign * value
