def merge_sorted(*iterables):
    import heapq

    # Create an iterator for each source with a unique index to maintain stability
    # The heap will store tuples: (value, source_index, iterator)
    # source_index ensures that if values are equal, the source with the lower index comes first (stable)

    heap = []
    for i, it in enumerate(iterables):
        try:
            first = next(it)
            heapq.heappush(heap, (first, i, it))
        except StopIteration:
            pass

    while heap:
        value, source_index, it = heapq.heappop(heap)
        yield value
        try:
            next_val = next(it)
            heapq.heappush(heap, (next_val, source_index, it))
        except StopIteration:
