from collections import defaultdict, deque

def topo_lex(graph):
    # graph maps a node to the list of nodes that depend on it (successors)
    # We need to compute in-degrees for all nodes
    # Nodes can appear only as keys, only as values, or both

    # Collect all nodes
    all_nodes = set(graph.keys())
    for successors in graph.values():
        for s in successors:
            all_nodes.add(s)

    # Compute in-degree for each node
    in_degree = {node: 0 for node in all_nodes}
    for node, successors in graph.items():
        for s in successors:
            in_degree[s] += 1

    # Initialize heap with nodes that have in-degree 0
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        # For each successor of this node, decrease in-degree
        if node in graph:
            for successor in graph[node]:
                in_degree[successor] -= 1
                if in_degree[successor] == 0:
                    heapq.heappush(heap, successor)

    if len(result) != len(all_nodes):
        return None

    return result
