      } else if (ch === ']') {
        if (inBracket) {
          parts.push(bracketContent);
          inBracket = false;
          bracketContent = '';
        } else {
          current += ch;
        }
      } else {
        if (inBracket) {
          bracketContent += ch;
        } else {
          current += ch;
        }
      }
    }
    if (current !== '') {
      parts.push(current);
    }

    // Set value in nested structure
    let target = obj;
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      const isLast = i === parts.length - 1;

      if (isLast) {
        // Handle array detection
        if (Array.isArray(target)) {
          // If part is empty string, it means a[] style, push to array
          if (part === '') {
            target.push(value);
          } else {
            // Numeric index
            const idx = parseInt(part, 10);
            if (!isNaN(idx) && String(idx) === part) {
              target[idx] = value;
            } else {
              // Non-numeric key on array? Treat as object property
              target[part] = value;
            }
          }
        } else if (target === null || typeof target !== 'object') {
          // Overwrite
          target = value;
        } else {
          // Check if this key already exists and is an array
          if (part in target) {
            if (Array.isArray(target[part])) {
              target[part].push(value);
            } else {
              // Convert to array
              target[part] = [target[part], value];
            }
          } else {
            target[part] = value;
          }
        }
      } else {
        // Navigate deeper
        if (part === '') {
          // a[] style: create array if not exists
          if (!Array.isArray(target)) {
            target = [];
            // We need to set this on the parent, but we're in the middle of traversal
            // This case is tricky. Let's handle it by ensuring the parent has an array.
            // Actually, if part is '', we expect the current target to be or become an array.
            // But we need to assign it to the parent's key.
            // Let's restructure: we need to track parent and key.
          }
          if (!Array.isArray(target)) {
            // This shouldn't happen in well-formed input, but handle it
            target = [];
          }
          // For a[], the next part is the index or we push
          // Actually, a[] means the value goes into an array at the previous key.
          // Let's rethink: parts for a[] is ['a', '']
          // When i=0, part='a', not last. We need to ensure obj['a'] is an array.
          // When i=1, part='', last. We push value.
          // So for non-last empty part, we need to create an array.
          if (!(part in target) || !Array.isArray(target[part])) {
            target[part] = [];
          }
          target = target[part];
        } else {
          if (!(part in target) || typeof target[part] !== 'object' || target[part] === null) {
            // Check if next part is empty (array style) or numeric
            const nextPart = parts[i + 1];
            if (nextPart === '' || (nextPart !== undefined && /^\d+$/.test(nextPart))) {
              target[part] = [];
            } else {
              target[part] = {};
            }
          }
          target = target[part];
        }
      }
    }
  }

  return obj;
}

function buildQuery(obj) {
  if (obj === null || obj === undefined || typeof obj !== 'object') {
    return '';
  }

  const pairs = [];

  function walk(current, prefix) {
    if (Array.isArray(current)) {
      for (let i = 0; i < current.length; i++) {
        const val = current[i];
        const key = prefix ? prefix + '[]' : '';
        if (val === null || val === undefined) {
          pairs.push(key + '=');
        } else if (typeof val === 'object' && val !== null) {
          walk(val, key);
        } else {
          pairs.push(key + '=' + encode(String(val)));
        }
      }
    } else {
      const keys = Object.keys(current).sort();
      for (const key of keys) {
        const val = current[key];
        const fullKey = prefix ? prefix + '[' + encode(key) + ']' : encode(key);
        if (val === null || val === undefined) {
          pairs.push(fullKey + '=');
        } else if (typeof val === 'object' && val !== null) {
          walk(val, fullKey);
        } else {
          pairs.push(fullKey + '=' + encode(String(val)));
        }
      }
    }
  }

  walk(obj, '');
  return pairs.join('&');
}

module.exports = { parseQuery, buildQuery };
