module.exports = function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];
  let isDispatching = false;

  function getState() {
    return state;
  }

  function dispatch(action) {
    if (isDispatching) {
      throw new Error('Dispatching from inside a reducer is not allowed');
    }

    isDispatching = true;
    state = reducer(state, action);
    const currentListeners = listeners.slice();
    for (let i = 0; i < currentListeners.length; i++) {
      currentListeners[i]();
    }
    isDispatching = false;
  }

  function subscribe(fn) {
    listeners.push(fn);
    return function unsubscribe() {
      const index = listeners.indexOf(fn);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }

  dispatch({ type: '@@INIT' });

  return {
    getState,
    dispatch,
    subscribe
  };
};

