module.exports = function toposortTasks(tasks) {
  const graph = {};
  const inDegree = {};
  const values = {};
  const dependents = {};
  const pending = {};
  const completed = new Set();
  const failed = [];

  // Initialize graph structures
  for (const name of Object.keys(tasks)) {
    graph[name] = tasks[name];
    inDegree[name] = 0;
    dependents[name] = [];
    pending[name] = 0;
  }

  // Build dependency graph and check for unknown dependencies
  for (const name of Object.keys(tasks)) {
    const task = tasks[name];
    const deps = task.deps || [];
    for (const dep of deps) {
      if (!tasks[dep]) {
        return Promise.reject(new Error(`Unknown dependency: ${dep}`));
      }
      inDegree[name]++;
      dependents[dep].push(name);
    }
  }

  // Detect cycles using Kahn's algorithm
  const queue = [];
  for (const name of Object.keys(tasks)) {
    if (inDegree[name] === 0) {
      queue.push(name);
    }
  }

  const visitedCount = 0;
  const tempQueue = [...queue];
  let count = 0;
  while (tempQueue.length > 0) {
    const current = tempQueue.shift();
    count++;
    for (const dep of dependents[current]) {
      inDegree[dep]--;
      if (inDegree[dep] === 0) {
        tempQueue.push(dep);
      }
    }
  }

  if (count !== Object.keys(tasks).length) {
    return Promise.reject(new Error('cycle detected'));
  }

  // Reset inDegree for actual execution
  for (const name of Object.keys(tasks)) {
    inDegree[name] = 0;
  }
  for (const name of Object.keys(tasks)) {
    const deps = tasks[name].deps || [];
    for (const dep of deps) {
      inDegree[name]++;
    }
  }

  // Find initial tasks with no dependencies
  const readyQueue = [];
  for (const name of Object.keys(tasks)) {
    if (inDegree[name] === 0) {
      readyQueue.push(name);
    }
  }

  return new Promise((resolve, reject) => {
    let completedCount = 0;
    const totalTasks = Object.keys(tasks).length;

    function runTask(name) {
      const task = tasks[name];
      const deps = task.deps || [];
      const depValues = {};
      for (const dep of deps) {
        depValues[dep] = values[dep];
      }

      task.run(depValues)
        .then((value) => {
          values[name] = value;
          completed.add(name);
          completedCount++;

          // Notify dependents
          for (const depName of dependents[name]) {
            inDegree[depName]--;
            if (inDegree[depName] === 0) {
              readyQueue.push(depName);
            }
          }

          // Check if all tasks are done
          if (completedCount === totalTasks) {
            if (failed.length > 0) {
              reject(failed[0]);
            } else {
              resolve(values);
            }
          }

          // Process any newly ready tasks
          processReady();
        })
        .catch((err) => {
          failed.push(err);
          completed.add(name);
          completedCount++;

          // Notify dependents (they will fail if they depend on this)
          for (const depName of dependents[name]) {
            inDegree[depName]--;
            if (inDegree[depName] === 0) {
              readyQueue.push(depName);
            }
          }

          if (completedCount === totalTasks) {
            reject(failed[0]);
          }

          processReady();
        });
    }

    function processReady() {
      // Run all currently ready tasks concurrently
      const currentReady = [...readyQueue];
      readyQueue.length = 0;
      for (const name of currentReady) {
        runTask(name);
      }
    }

    // Start with initial ready tasks
    processReady();
  });
};
