export class Bus<E extends Record<string, unknown>> {
  private listeners = new Map<keyof E, Array<(payload: any) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const list = this.listeners.get(k);
    if (list) {
      list.push(fn);
    } else {
      this.listeners.set(k, [fn]);
    }
    return () => {
      const list = this.listeners.get(k);
      if (list) {
        const idx = list.indexOf(fn);
        if (idx !== -1) {
          list.splice(idx, 1);
        }
      }
    };
  }

  emit<K extends keyof E>(k: K, payload?: E[K] extends void ? never : E[K]): void {
    const list = this.listeners.get(k);
    if (list) {
      for (const fn of list) {
        fn(payload as any);
      }
    }
  }
}

