  [P in T['kind']]: (value: Extract<T, { kind: P }>) => any;
};

export function match<T extends { kind: string }, K extends T['kind']>(
  value: T,
  handlers: { [P in K]: (value: Extract<T, { kind: P }>) => any }
): ReturnType<Required<{ [P in K]: (value: Extract<T, { kind: P }>) => any }>['kind']> {
