export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends Array<infer U>
  ? Array<DeepAwaited<U>>
  : T extends Record<string, unknown>
  ? { [K in keyof T]: DeepAwaited<T[K]> }
  : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value instanceof Promise) {
    return deepAwait(await value);
  }
  if (Array.isArray(value)) {
    return (await Promise.all(value.map((item) => deepAwait(item)))) as DeepAwaited<T>;
  }
  if (value !== null && typeof value === 'object') {
    const keys = Object.keys(value);
    const resolvedEntries = await Promise.all(
      keys.map(async (key) => {
        const resolvedValue = await deepAwait((value as Record<string, unknown>)[key]);
        return [key, resolvedValue] as const;
      })
    );
    const result: Record<string, unknown> = {};
    for (const [key, val] of resolvedEntries) {
      result[key] = val;
    }
    return result as DeepAwaited<T>;
  }
  return value as DeepAwaited<T>;
}

