export function curry(fn: (...args: any[]) => any): any {
    const arity = fn.length;
    if (arity === 0) {
        return fn;
    }

    function createCurried(arity: number, args: any[]): any {
        if (args.length >= arity) {
            return fn(...args);
        }

        function curried(...nextArgs: any[]): any {
            return createCurried(arity, [...args, ...nextArgs]);
        }

        return curried;
    }

    return createCurried(arity, []);
}

