type PickKeys<T, K extends keyof T> = {
  [P in K]: T[P];
};

type OmitKeys<T, K extends keyof T> = {
  [P in Exclude<keyof T, K>]: T[P];
};

export function pick<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): PickKeys<T, K> {
  const result = {} as PickKeys<T, K>;
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      (result as any)[key] = (obj as any)[key];
    }
  }
  return result;
}

export function omit<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): OmitKeys<T, K> {
  const result = {} as OmitKeys<T, K>;
  for (const key of Object.keys(obj) as Array<keyof T>) {
    if (!keys.includes(key as K)) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        (result as any)[key] = (obj as any)[key];
      }
    }
  }
  return result;
}
