export type DeepPartial<T> = T extends (...args: any[]) => any
  ? T
  : T extends Array<infer U>
  ? DeepPartialArray<U>
  : T extends object
  ? DeepPartialObject<T>
  : T | undefined;

type DeepPartialArray<T> = Array<DeepPartial<T>>;

type DeepPartialObject<T> = {
  [P in keyof T]?: DeepPartial<T[P]>;
};

export function applyPatch<T extends object>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined || patch === null) {
    return base;
  }

  const result = { ...base };

  for (const key of Object.keys(patch) as (keyof typeof patch)[]) {
    const patchValue = patch[key];

    if (patchValue === undefined) {
      continue;
    }

    if (Array.isArray(patchValue)) {
      (result as any)[key] = patchValue;
    } else if (typeof patchValue === 'object' && patchValue !== null && !Array.isArray(patchValue)) {
      const baseValue = (base as any)[key];
      if (typeof baseValue === 'object' && baseValue !== null && !Array.isArray(baseValue)) {
        (result as any)[key] = applyPatch(baseValue, patchValue);
      } else {
        (result as any)[key] = patchValue;
      }
    } else {
      (result as any)[key] = patchValue;
    }
  }

  return result;
}
